"""Compile H891 rank1 cross-vector approximation into two scalar coefficients."""
from run_bilin18_agreement_partner_number import ART,load_full_model,sha
from pathlib import Path
import torch,json
@torch.inference_mode()
def main():
 torch.set_num_threads(6);torch.set_float32_matmul_precision('highest');S='bilin18_number_interaction_compression';paths={'fits':ART/f'{S}_fits.pt','axes':ART/'bilin18_agreement_partner_number_fits.pt','centroids':ART/'bilin18_agreement_partner_number.json','states':ART/'bilin18_number_transfer_screen_captures.pt','runner':Path(__file__)};hashes={k:sha(p) for k,p in paths.items()};fit=torch.load(paths['fits'],weights_only=False);axes=torch.load(paths['axes'],weights_only=False);old=json.loads(paths['centroids'].read_text());panel=torch.load(paths['states'],weights_only=False);d=json.loads((ART/f'{S}.json').read_text());model=load_full_model('cuda');model.blocks.float();mod=model.blocks[12].mlp;L,R,D=[m.weight.double() for m in [mod.Left,mod.Right,mod.Down]];eps=torch.finfo(torch.float32).eps;units={};maxcoef=0.;maxwrite=0.
 for (axis,family),(mu,basis,random) in fit.items():
  mu=mu.cuda();v=basis[0].cuda();mean,B,_=axes['agreement','task',axis,12];b=B[0].cuda();meanb=mean.cuda()@b;cc=torch.tensor(next(r['centroids'] for r in old['geometry'] if (r['family'],r['format'],r['layer'],r['split'])==('task',axis,12,'discovery')),device='cuda',dtype=torch.double);origin=meanb+cc.mean();back=D.T@v;a=L.T@((R@b)*back)+R.T@((L@b)*back);encoder=a-(a@b)*b;offset=origin*(a@b)-mu@v
  inds=[i for i in d['selection'] if panel['examples'][i]['family']==family];x=torch.stack([panel['states'][i][12] for i in inds]).cuda();u=x/(x.square().mean(-1,keepdim=True)+eps).sqrt();w=u-((u@b)-origin)[:,None]*b;C=((w@L.T)*(b@R.T)+(w@R.T)*(b@L.T))@D.T;ref=(C-mu)@v;compiled=u@encoder+offset;maxcoef=max(maxcoef,float((ref-compiled).abs().max()));shift=cc[1-torch.tensor([panel['examples'][i]['order'] for i in inds],device='cuda')]-(u@b-meanb);expected=shift[:,None]*(mu+ref[:,None]*v);actual=shift[:,None]*mu+(shift*compiled)[:,None]*v;maxwrite=max(maxwrite,float((actual-expected).norm()/expected.norm()));units[axis,family]={'number_axis':b.cpu(),'number_origin':float(origin),'native_mean_projection':float(meanb),'number_centroids':cc.cpu(),'context_encoder':encoder.cpu(),'context_offset':float(offset),'output_mean':mu.cpu(),'output_direction':v.cpu()}
 assert maxcoef<1e-7 and maxwrite<1e-10
 torch.save(units,ART/f'{S}_compiled_units.pt');p=ART/f'{S}_analysis.json';result=json.loads(p.read_text());result['compilation_audit']={'coefficient_max_abs':maxcoef,'write_relative_error':maxwrite,'hashes_unchanged':all(sha(p)==hashes[k] for k,p in paths.items()),'hashes':hashes,'scope':'Two-output-direction approximation of centered cross-term change only: delta*mu + delta*(encoder.u+offset)*v. Encoder obtained analytically from fixed weights and discovery PCA; no new fitting. All120 selected native states.'};assert result['compilation_audit']['hashes_unchanged'];p.write_text(json.dumps(result,indent=2)+'\n');print(result['compilation_audit'])
if __name__=='__main__':main()
